    grid2.setColumnOrder('col2', 'col1');
};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#grid2_column3', 'drag-n-drop', {
        dx: -10,
        dy: -50
    });
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 'setColumnOrder'버튼을 클릭한다.
    //1. After running the sample, click the 'setColumnOrder' button.
    //Verify step 1. The order of classification 1 and classification 2 is changed to classification 2 and classification 1. (col1, col2 -> col2, col1)
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger4').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid2_column3').text() == '분류2'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid2_column5').text() == '분류1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. '분류2'항목을 groupby 시킨다.
    //2. Group the item 'Category 2'.
    //Verify step 2. Text will be output as 'Classification 2' item name.
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_column_value').text() == '분류2'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 3. groupby filter를 클릭하여 확인한다.
    //3. Click the groupby filter to confirm.
    //Verify step 3. Filter list of 0,1, A, B, C is shown.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_column').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_list_listColumn_text')[2].innerText == '0'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_list_listColumn_text')[3].innerText == '1'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_list_listColumn_text')[4].innerText == 'A'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_list_listColumn_text')[5].innerText == 'B'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_list_listColumn_text')[6].innerText == 'C'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
